(()=>{const PRICE='QAR 200';function fix(){document.querySelectorAll('.product-card,.oud-card').forEach(card=>{const name=(card.querySelector('h3')?.textContent||'').trim().toLowerCase();if(name==='bakhoor burner'||name==='مبخرة'){let p=card.querySelector('.price');if(!p){p=document.createElement('p');p.className='price';const btn=card.querySelector('button,.card-add');btn?btn.before(p):card.appendChild(p)}p.textContent=PRICE}});if(/\/products\/bakhoor-burner\/?$/.test(location.pathname)){const info=document.querySelector('.product-info');if(info){let p=info.querySelector('.product-price,.price');if(p)p.textContent=PRICE}}}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',fix);else fix();window.addEventListener('load',fix);setTimeout(fix,300);setTimeout(fix,1200);new MutationObserver(fix).observe(document.documentElement,{childList:true,subtree:true})})();